import {AIRPORTS,PLANES,RIVALS,QUESTS,EVENTS,UPGRADES} from './data.js';
import * as C from './career.js';
export {SPECIALIZATIONS, CONTRACT_TYPES, careerState, strategyCredits, routeMastery, contractType, contractQualifies, initializeCareer, acceptContract, abandonContract, setAircraftGoal} from './career.js';
import {WORLD_EVENT_TYPES,MARKET_ENTRANT,createWorldCalendar} from './world-events.js';
const airportIndex=new Map(AIRPORTS.map(a=>[a.id,a])),modelIndex=new Map(PLANES.map(p=>[p.id,p]));export const ap=id=>airportIndex.get(id);export const model=id=>modelIndex.get(id);export const clamp=(n,a,b)=>Math.min(b,Math.max(a,n));export const key=(a,b)=>[a,b].sort().join('-');
export const gameDay=s=>Math.floor(s.minute/1440);
export const airportOpen=(s,id)=>!!ap(id)&&gameDay(s)>=(ap(id).opensDay||0);
export const openAirports=s=>AIRPORTS.filter(a=>airportOpen(s,a.id));
export const modelStatus=(s,m)=>gameDay(s)<m.releaseDay?'upcoming':gameDay(s)>=m.retireDay?'legacy':'production';
export const releasedPlanes=s=>PLANES.filter(m=>modelStatus(s,m)!=='upcoming');
export const aircraftPrice=(s,id)=>Math.round(model(id).price*(modelStatus(s,model(id))==='legacy'?.55:1));
export function resaleValue(s,p){if(p.leased)return Math.round((p.paid||model(p.model).price*.14)*.5);const age=Math.max(0,gameDay(s)-(p.acquiredDay||0)),factor=Math.max(.32,.7-age*.0007-(modelStatus(s,model(p.model))==='legacy'?.06:0));return Math.round((p.paid||model(p.model).price)*factor);}
export function nextWorldEvent(s){const day=gameDay(s),nextAirport=AIRPORTS.filter(a=>a.opensDay>day).sort((a,b)=>a.opensDay-b.opensDay)[0],nextPlane=PLANES.filter(m=>m.releaseDay>day).sort((a,b)=>a.releaseDay-b.releaseDay)[0];return {nextAirportDay:nextAirport?.opensDay??null,nextPlaneDay:nextPlane?.releaseDay??null,airports:openAirports(s).length,aircraft:releasedPlanes(s).length};}
export function distance(a,b){a=typeof a==='string'?ap(a):a;b=typeof b==='string'?ap(b):b;const r=Math.PI/180,dl=(b.lat-a.lat)*r,dg=(b.lon-a.lon)*r;return Math.round(6371*2*Math.asin(Math.sqrt(Math.sin(dl/2)**2+Math.cos(a.lat*r)*Math.cos(b.lat*r)*Math.sin(dg/2)**2)));}
export const licensePrice=(a,b)=>Math.round((18000+distance(a,b)*32+(ap(a).demand+ap(b).demand)*950)/1000)*1000;
export const airportShare=s=>s.upgrades.includes('terminal')?.04:.03;
export const event=s=>EVENTS[Math.floor(s.minute/4320)%EVENTS.length];
export function createGame(){return {version:1,name:'Aerovale Airways',color:'#4b84ff',home:'SLC',cash:480000,minute:480,speed:1,started:false,created:Date.now(),worldEvents:createWorldCalendar(0),notifications:[],lastSave:Date.now(),planes:[],routes:[],airports:[],claims:[],upgrades:[],reputation:75,debt:0,bailout:false,nextId:1,nextAI:1920,aiTurn:0,aiBid:null,log:[{time:480,text:'Your operating license is approved. Welcome aboard, captain.',type:'company'}],ledger:[],history:[{day:0,cash:480000,worth:480000}],totals:{revenue:0,fuel:0,crew:0,maintenance:0,fees:0,airport:0,flights:0,passengers:0,interest:0,leases:0,rewards:0},rivals:RIVALS.map((r,i)=>({...r,cash:r.cash,nextExpansionAt:1920+i*240,expansionTurn:0,expansionStatus:'scouting',bid:null,routes:r.routes.map(([a,b])=>({a,b,id:key(a,b),progress:0,model:i===1?'a321':i===3?'a220':'e175'})),revenue:0,flights:0,airports:[]}))};}
export const connected=s=>[...new Set([s.home,...s.routes.flatMap(r=>[r.a,r.b])])];
export const ROUTE_LICENSE_LIMIT=5;
export const routeLicenseCount=r=>r.licenses??1;
export const airlineLicenses=s=>s.routes.reduce((n,r)=>n+routeLicenseCount(r),0);
export const slots=(s,a,b)=>s.rivals.reduce((n,r)=>n+r.routes.filter(t=>t.id===key(a,b)).reduce((sum,t)=>sum+routeLicenseCount(t),0),0)+s.routes.filter(r=>r.id===key(a,b)).reduce((n,r)=>n+routeLicenseCount(r),0);
export const remainingLicenses=(s,a,b)=>Math.max(0,ROUTE_LICENSE_LIMIT-slots(s,a,b));

export const eventDefinition=id=>WORLD_EVENT_TYPES.find(e=>e.id===id);
const allRivalDefinitions=[...RIVALS,MARKET_ENTRANT];
export const activeWorldEvents=s=>(s.worldEvents?.active||[]).filter(e=>gameDay(s)>=e.startDay&&gameDay(s)<e.endDay);
export const upcomingWorldEvents=s=>s.worldEvents?.upcoming||[];
export const eventAffects=(e,a,b)=>e.scope==='global'||(e.scope==='city'?[a,b].includes(e.airport):[ap(a).region,ap(b).region].includes(e.region));
export function worldEffects(s,a,b){const out={demand:1,yield:1,fuel:1,time:1};for(const e of activeWorldEvents(s)){if(!eventAffects(e,a,b))continue;const def=eventDefinition(e.type);for(const k of Object.keys(out))out[k]*=def[k];}return out;}
export function marketConditions(s,a,b){const base=event(s),extra=worldEffects(s,a,b);return {demand:clamp(base.demand*extra.demand,.65,2.25),yield:clamp(extra.yield,.85,1.35),fuel:clamp(base.fuel*extra.fuel,.65,1.55),time:clamp(base.time*extra.time,1,1.4)};}
export const unreadNotifications=s=>(s.notifications||[]).filter(n=>!n.read);
export function notify(s,n){s.notifications??=[];if(s.notifications.some(x=>x.id===n.id))return;const item={...n,time:s.minute,read:false,shown:false};s.notifications.unshift(item);s.notifications=s.notifications.slice(0,300);}
export function markNotificationsRead(s,id=null){for(const n of s.notifications||[])if(id===null||n.id===id){n.read=true;n.shown=true;}}
export function newcomerInfo(s){const w=s.worldEvents,ai=s.rivals.find(ai=>ai.id===MARKET_ENTRANT.id);return {name:MARKET_ENTRANT.name,base:MARKET_ENTRANT.base,status:ai?'arrived':w?.entrantAnnounced?'announced':'unannounced',day:w?.entrantDay??gameDay(s)+18,budget:w?.entrantBudget??25000000};}
function eventLocation(e){return e.scope==='city'?ap(e.airport).city:e.scope==='region'?e.region:'Worldwide';}
export function eventTitle(e){return eventDefinition(e.type).name+(e.scope==='global'?'':' · '+eventLocation(e));}
function eventNotification(s,e,phase){const def=eventDefinition(e.type),day=gameDay(s),title=eventTitle(e);notify(s,{id:e.id+':'+phase,kind:'event',title:phase==='announced'?title+' announced':phase==='started'?title+' is live':title+' has ended',message:phase==='ended'?'Event effects have expired. Check your route forecasts for current conditions.':`${def.effect}. ${eventLocation(e)}. ${phase==='announced'?'Starts on day '+(e.startDay+1):'Active now'}; ends on day ${e.endDay+1}. Applies to new departures.`,eventId:e.id});log(s,`${title}: ${phase==='announced'?'begins on day '+(e.startDay+1):phase==='started'?'now active until day '+(e.endDay+1):'ended on day '+(day+1)}.`,'event');}
function planWorldEvent(s){
 const w=s.worldEvents,sequence=w.sequence++,day=gameDay(s),previous=[...w.upcoming,...w.active,...w.history].sort((a,b)=>b.startDay-a.startDay)[0]?.type;
 const types=WORLD_EVENT_TYPES.filter(e=>e.id!==previous),seed=String(s.created||0)+':'+w.epochDay+':'+sequence;
 // The opening event is an opportunity; later events vary in kind, place and spacing.
 const def=sequence===0?WORLD_EVENT_TYPES[0]:types[Math.floor(aiNoise(seed+':type')*types.length)],open=openAirports(s),regions=[...new Set(open.map(a=>a.region))],region=regions[Math.floor(aiNoise(seed+':region')*regions.length)];
 const pool=def.scope==='city'?open.filter(a=>a.demand>=7):def.scope==='region'?open.filter(a=>a.region===region):open;
 const target=pool[Math.floor(aiNoise(seed+':airport')*pool.length)],startDay=day+def.notice;
 const e={id:'world-'+w.epochDay+'-'+sequence,type:def.id,scope:def.scope,airport:target.id,region:target.region,startDay,endDay:startDay+def.duration};
 w.upcoming.push(e);w.nextAnnouncementDay=day+9+Math.floor(aiNoise(seed+':interval')*5);eventNotification(s,e,'announced');
}
function advanceWorld(s){
 s.worldEvents??=createWorldCalendar(gameDay(s));s.notifications??=[];const w=s.worldEvents,day=gameDay(s);
 for(const e of w.active.filter(e=>day>=e.endDay)){eventNotification(s,e,'ended');w.history.unshift(e);}w.active=w.active.filter(e=>day<e.endDay);w.history=w.history.slice(0,24);
 for(const e of w.upcoming.filter(e=>day>=e.startDay)){if(day<e.endDay)w.active.push(e);else w.history.unshift(e);eventNotification(s,e,day<e.endDay?'started':'ended');}w.upcoming=w.upcoming.filter(e=>day<e.startDay);w.history=w.history.slice(0,24);
 if(day>=w.nextAnnouncementDay)planWorldEvent(s);
 if(!s.rivals.some(ai=>ai.id===MARKET_ENTRANT.id)){
  if(!w.entrantAnnounced&&day>=w.entrantDay-4){w.entrantAnnounced=true;w.entrantBudget=Math.round(clamp(netWorth(s)*.6,25000000,150000000));notify(s,{id:'apex-announced',kind:'rival',title:'A well-funded challenger is coming',message:`${MARKET_ENTRANT.name} has secured $${Math.round(w.entrantBudget/1e6)}m and plans to launch from ${MARKET_ENTRANT.base} on day ${w.entrantDay+1}. It must buy the same limited licenses and announce its purchases.`});log(s,`${MARKET_ENTRANT.name} announces a $${Math.round(w.entrantBudget/1e6)}m launch on day ${w.entrantDay+1}.`,'rival');}
  if(day>=w.entrantDay){s.rivals.push({...MARKET_ENTRANT,cash:w.entrantBudget,routes:[],revenue:0,flights:0,airports:[],nextExpansionAt:s.minute+720,expansionTurn:0,expansionStatus:'scouting',bid:null});notify(s,{id:'apex-arrived',kind:'rival',title:MARKET_ENTRANT.name+' has entered the market',message:`A $${Math.round(w.entrantBudget/1e6)}m treasury is ready for expansion from ${MARKET_ENTRANT.base}. Watch its announced plans and protect your most valuable connections.`});log(s,`${MARKET_ENTRANT.name} enters the market with $${Math.round(w.entrantBudget/1e6)}m. Its first route review is in 12 game hours.`,'rival');}
 }
}
function validateWorldState(s){
 if(s.notifications!==undefined){if(!Array.isArray(s.notifications)||s.notifications.length>300||new Set(s.notifications.map(n=>n.id)).size!==s.notifications.length)throw Error('Invalid notifications.');for(const n of s.notifications){if(!n||typeof n.id!=='string'||n.id.length>90||!['airports','aircraft','event','rival','career'].includes(n.kind)||typeof n.title!=='string'||n.title.length>200||typeof n.message!=='string'||n.message.length>1500||!Number.isFinite(n.time)||n.time<0||typeof n.read!=='boolean'||typeof n.shown!=='boolean')throw Error('Invalid notification.');if(n.items!==undefined&&(!Array.isArray(n.items)||n.items.length>600||n.items.some(id=>n.kind==='airports'?!ap(id):n.kind==='aircraft'?!model(id):true)))throw Error('Invalid notification details.');if(n.eventId!==undefined&&(typeof n.eventId!=='string'||n.eventId.length>90))throw Error('Invalid event link.');}}
 const w=s.worldEvents;if(w===undefined)return;if(!w||w.version!==1||['epochDay','sequence','nextAnnouncementDay','entrantDay'].some(k=>!Number.isInteger(w[k])||w[k]<0)||typeof w.entrantAnnounced!=='boolean'||(w.entrantBudget!==null&&(!Number.isFinite(w.entrantBudget)||w.entrantBudget<0)))throw Error('Invalid world calendar.');
 const ids=new Set();for(const field of ['active','upcoming','history']){if(!Array.isArray(w[field])||w[field].length>24)throw Error('Invalid world events.');for(const e of w[field]){const d=eventDefinition(e?.type);if(!d||typeof e.id!=='string'||e.id.length>90||ids.has(e.id)||e.scope!==d.scope||!ap(e.airport)||e.region!==ap(e.airport).region||!Number.isInteger(e.startDay)||e.startDay<0||e.endDay!==e.startDay+d.duration)throw Error('Invalid world event.');ids.add(e.id);}}
}

export function routeDemand(s,a,b){return Math.round((ap(a).demand+ap(b).demand)*62*(1+Math.min(distance(a,b),6000)/15000)*marketConditions(s,a,b).demand*(s.upgrades.includes('marketing')?1.12:1));}
export function economics(s,r,p,{rivals=false}={}){
 const m=model(p.model),conditions=marketConditions(s,r.a,r.b),km=distance(r.a,r.b),fare=r.fare||1,cabin=p.cabin||'standard';
 const career=rivals?{yield:1,seats:.73,demand:1,time:1,crew:1,fuel:1,maintenance:1}:C.careerEffects(s,r,cabin,km);
 const seats=Math.floor(m.seats*(cabin==='premium'?career.seats:cabin==='dense'?1.14:1)),duration=(km/m.speed*120+(s.upgrades.includes('turnaround')?20:36))*conditions.time*career.time;
 const competition=Math.max(0,slots(s,r.a,r.b)-(rivals||s.routes.some(x=>x.id===key(r.a,r.b))?1:0)),demand=routeDemand(s,r.a,r.b)*career.demand/Math.max(1,1+competition*.38);
 const marketLoad=clamp(.85+(s.reputation-75)*.006-(fare-1)*.66+(cabin==='premium'?.015:cabin==='dense'?-.06:0),.25,.98),capacityLoad=clamp(demand/(seats*2*(1440/duration)),.15,1),load=Math.min(marketLoad,capacityLoad),pax=Math.floor(seats*2*load);
 const ticket=(44+km*.13)*fare*conditions.yield*(cabin==='premium'?1.58*(s.upgrades.includes('premium')?1.1:1):1)*career.yield,revenue=Math.round(pax*ticket);
 const fuel=Math.round(km*2*m.burn*.9*conditions.fuel*(s.upgrades.includes('efficiency')?.92:1)*career.fuel),crew=Math.round((duration/60)*(110+seats*1.4)*career.crew);
 const maintenance=Math.round(km*m.seats*.012*(1+Math.min(1.25,Math.max(0,gameDay(s)-(p.acquiredDay||0))/240)+(modelStatus(s,m)==='legacy'?.25:0))*career.maintenance),fees=Math.round(revenue*.03),profit=revenue-fuel-crew-maintenance-fees;
 return {km,duration,load,seats,pax,ticket,revenue,fuel,crew,maintenance,fees,profit};
}
export function claimContract(s,id){const contract=C.collectContract(s,id);money(s,contract.reward,C.contractType(contract.type).title+' · contract','reward');s.totals.rewards+=contract.reward;log(s,C.contractType(contract.type).title+' completed. Commission and 1 strategy credit earned.','career');return contract;}
export function developSpecialization(s,id){const step=C.developSpecialization(s,id);log(s,step.name+' developed. '+step.effect,'career');return step;}
export function rotationStats(s,p){const rent=p.leased?(p.leaseRate??model(p.model).price*.018):0;const rs=p.schedule.map(id=>s.routes.find(r=>r.id===id)).filter(Boolean);if(!rs.length)return {daily:-rent,duration:0};const es=rs.map(r=>economics(s,r,p)),duration=es.reduce((n,e)=>n+e.duration,0);return {duration,daily:(p.auto?es.reduce((n,e)=>n+e.profit,0)*1440/duration:0)-rent};}
export function airportDaily(s,id){const effects=worldEffects(s,id,id);let revenue=ap(id).demand*47000*effects.demand*effects.yield;for(const p of s.planes){if(!p.auto)continue;const duration=rotationStats(s,p).duration;if(!duration)continue;for(const rid of p.schedule){const r=s.routes.find(x=>x.id===rid);if(r&&(r.a===id||r.b===id))revenue+=economics(s,r,p).revenue*1440/duration/2;}}for(const ai of s.rivals)for(const r of ai.routes)if(r.a===id||r.b===id){const e=economics(s,r,{model:r.model},{rivals:true});revenue+=e.revenue*1440/e.duration/2;}return Math.round(revenue*airportShare(s));}
export function dailyProfit(s){return s.planes.reduce((n,p)=>n+rotationStats(s,p).daily,0)+s.airports.reduce((n,a)=>n+airportDaily(s,a),0)-s.debt*.002;}
export function netWorth(s){return s.cash+s.planes.filter(p=>!p.leased).reduce((n,p)=>n+resaleValue(s,p),0)+s.routes.reduce((n,r)=>n+r.paid*.7,0)+s.airports.reduce((n,id)=>n+ap(id).price,0)-s.debt;}
export function questValue(s,q){const map={planes:s.planes.length,routes:s.routes.length,flights:s.totals.flights,passengers:s.totals.passengers,revenue:s.totals.revenue,airports:s.airports.length,upgrades:s.upgrades.length,destinations:connected(s).length,longest:Math.max(0,...s.routes.filter(r=>s.planes.some(p=>p.schedule.includes(r.id))).map(r=>distance(r.a,r.b))),continents:new Set(connected(s).map(id=>ap(id).region)).size,widebody:s.planes.filter(p=>model(p.model).seats>=296).length,worth:netWorth(s),newairport:connected(s).filter(id=>ap(id).opensDay>0).length,generation:Math.max(0,...s.planes.map(p=>model(p.model).generation)),replacements:s.totals.replacements||0};return map[q.type]||0;}
export function log(s,text,type='company'){s.log.unshift({time:s.minute,text,type});s.log=s.log.slice(0,45);}
function money(s,amount,label,category){s.cash+=amount;s.ledger.unshift({time:s.minute,amount,label,category});s.ledger=s.ledger.slice(0,100);}
function pay(s,amount){if(!Number.isFinite(amount)||amount<0)throw Error('Invalid amount.');if(s.cash<amount)throw Error('You need more available funds for this purchase.');}
export function buyPlane(s,id,leased=false){const m=model(id);if(!m)throw Error('Choose an aircraft.');if(modelStatus(s,m)==='upcoming')throw Error(`This model enters the market on game day ${m.releaseDay+1}.`);if(s.routes.length<m.unlock)throw Error(`Own ${m.unlock} routes to unlock this aircraft.`);if(s.planes.length>=150)throw Error('Your airline can operate up to 150 aircraft.');const cost=Math.round(aircraftPrice(s,id)*(leased?.14:1));pay(s,cost);money(s,-cost,`${leased?'Lease deposit':'Aircraft purchase'} · ${m.name}`,'investment');s.planes.push({id:`AV${String(s.nextId++).padStart(3,'0')}`,model:id,leased,paid:cost,leaseRate:aircraftPrice(s,id)*.018,acquiredDay:gameDay(s),cabin:'standard',schedule:[],leg:0,progress:0,flight:null,auto:true,condition:100,flights:0,revenue:0,base:s.home,repair:0});s.started=true;log(s,`${m.name} joins your fleet. Ready for its first rotation.`);return s.planes.at(-1);}
export function buyRoute(s,a,b){if(!ap(a)||!ap(b)||a===b)throw Error('Select two different airports.');if(!airportOpen(s,a)||!airportOpen(s,b))throw Error('This airport has not opened yet.');if(!remainingLicenses(s,a,b))throw Error(`Sold out. All ${ROUTE_LICENSE_LIMIT} licenses for ${a}–${b} are owned. No more can be purchased.`);if(!connected(s).includes(a)&&!connected(s).includes(b))throw Error('Connect this route to your existing network.');if(!s.planes.some(p=>model(p.model).range>=distance(a,b)))throw Error('Acquire an aircraft with enough range first.');const price=licensePrice(a,b);pay(s,price);money(s,-price,`Route license · ${a}–${b}`,'investment');let r=s.routes.find(r=>r.id===key(a,b));if(r){r.licenses=routeLicenseCount(r)+1;r.paid+=price;}else{r={id:key(a,b),a,b,fare:1,paid:price,flights:0,revenue:0};s.routes.push(r);}log(s,`Route secured: ${a}–${b}. Your license is permanent. ${remainingLicenses(s,a,b)} of ${ROUTE_LICENSE_LIMIT} licenses remain.`);return r;}
function rotationPlan(s,id,ids,cabin='standard'){const p=s.planes.find(x=>x.id===id);if(!p)throw Error('Aircraft not found.');if(p.flight)throw Error('Pause departures, then wait for this round trip to finish before changing the rotation.');if(!['standard','premium','dense'].includes(cabin))throw Error('Choose a valid cabin.');ids=[...new Set(ids)];if(ids.length>6)throw Error('A rotation supports up to 6 routes.');for(const rid of ids){const r=s.routes.find(x=>x.id===rid);if(!r)throw Error('You must own each route.');if(distance(r.a,r.b)>model(p.model).range)throw Error('This route exceeds the aircraft’s range.');if(s.planes.filter(x=>x.id!==id&&x.schedule.includes(rid)).length>=routeLicenseCount(r))throw Error('All your licenses on this connection already have an aircraft. Buy another available license to add capacity.');}let common=ids.length? [s.routes.find(r=>r.id===ids[0]).a,s.routes.find(r=>r.id===ids[0]).b]:[p.base];for(const rid of ids){const r=s.routes.find(x=>x.id===rid);common=common.filter(x=>x===r.a||x===r.b);}if(!common.length)throw Error('All round-trip routes in a rotation must share one base airport.');const base=common.includes(p.base)?p.base:common[0];const relocation=base!==p.base?Math.round(distance(base,p.base)*model(p.model).burn):0;pay(s,relocation);return {p,ids,base,relocation,cabin};}
export function schedulePlane(s,id,ids,cabin='standard'){const plan=rotationPlan(s,id,ids,cabin),{p,base,relocation}=plan;if(relocation)money(s,-relocation,`Ferry relocation · ${id}`,'operations');p.base=base;p.schedule=plan.ids;p.cabin=cabin;p.leg=0;p.progress=0;p.auto=true;log(s,`${id} rotation updated: ${plan.ids.length} route${plan.ids.length===1?'':'s'}, automatic departures on.`);}
export function routeAssignment(s,routeId,planeId){const p=s.planes.find(p=>p.id===planeId);if(!p)throw Error('Aircraft not found.');if(p.schedule.includes(routeId))throw Error('Already assigned to this connection.');return rotationPlan(s,planeId,[...p.schedule,routeId],p.cabin);}
export function assignPlaneToRoute(s,routeId,planeId){const {ids,cabin}=routeAssignment(s,routeId,planeId);schedulePlane(s,planeId,ids,cabin);}
export function claimQuest(s,id){const q=QUESTS.find(q=>q.id===id);if(!q||s.claims.includes(id))throw Error('Reward already claimed or unavailable.');if(questValue(s,q)<q.target)throw Error('Complete the objective first.');s.claims.push(id);s.totals.rewards+=q.reward;money(s,q.reward,`Objective · ${q.title}`,'reward');log(s,`${q.title} complete. Bonus earned: $${q.reward.toLocaleString()}.`);}
export function buyAirport(s,id){const a=ap(id);if(!a)throw Error('Airport not found.');if(!airportOpen(s,id))throw Error(`This airport opens on game day ${a.opensDay+1}.`);if(s.airports.includes(id))throw Error('You already own this airport.');if(!connected(s).includes(id))throw Error('Connect this airport to your network first.');pay(s,a.price);money(s,-a.price,`Airport acquisition · ${id}`,'investment');s.airports.push(id);log(s,`You now own ${a.city} airport. All carriers contribute to your revenue.`);}
export function buyUpgrade(s,id){const u=UPGRADES.find(x=>x.id===id);if(!u||s.upgrades.includes(id))throw Error('Improvement unavailable.');pay(s,u.cost);money(s,-u.cost,u.name,'investment');s.upgrades.push(id);if(id==='service')s.reputation=Math.min(100,s.reputation+5);log(s,`${u.name} is now active across your airline.`);}
export function setFare(s,id,fare){const r=s.routes.find(r=>r.id===id);fare=Number(fare);if(!r||fare<.7||fare>1.6||!Number.isFinite(fare))throw Error('Fare must be between 70% and 160%.');r.fare=fare;}
export function sellPlane(s,id){const p=s.planes.find(x=>x.id===id);if(!p)throw Error('Aircraft not found.');if(p.flight)throw Error('Finish the current round trip before selling or returning the aircraft.');const value=resaleValue(s,p);money(s,value,`${p.leased?'Lease return':'Aircraft sale'} · ${id}`,'investment');s.planes=s.planes.filter(x=>x.id!==id);}
export function servicePlane(s,id){const p=s.planes.find(x=>x.id===id);if(!p)throw Error('Aircraft not found.');if(p.flight)throw Error('Service is available after the current round trip.');const cost=Math.round(model(p.model).price*.01);pay(s,cost);money(s,-cost,`Preventive service · ${id}`,'operations');s.totals.maintenance+=cost;p.condition=100;p.repair=90;}
export function borrow(s,amount){amount=Number(amount);const limit=Math.max(150000,Math.min(5000000,netWorth(s)*.5));if(!Number.isFinite(amount)||amount<=0||amount%1000)throw Error('Enter a positive amount in multiples of $1,000.');if(s.debt+amount>limit)throw Error(`Your credit limit is $${Math.floor(limit/1000)*1000}.`);s.debt+=amount;money(s,amount,'Business credit draw','financing');}
export function repay(s,amount){amount=Number(amount);if(!Number.isFinite(amount)||amount<=0||amount>s.debt)throw Error('Enter an amount up to your outstanding debt.');pay(s,amount);s.debt-=amount;money(s,-amount,'Business credit repayment','financing');}
export function rescue(s){if(s.cash>=25000||s.bailout)throw Error('The recovery grant is available once, below $25,000 cash.');s.bailout=true;money(s,125000,'Small airline recovery grant','financing');log(s,'Recovery funding approved. Review your route profitability before expanding.');}

export const AI_STRATEGIES={
 apex:{label:'Capital-backed challenger',description:'Starts with deep reserves and builds a selective Dubai network. Pays for every license and aircraft, scouts imperfectly, and announces purchases before acting.',distance:5000,spread:5500,maxDistance:11000,maxSeats:350,seats:244,regions:['Asia','Europe','Africa'],hub:.3,repeat:.08,scarcity:.08,contest:.05,reserve:1.6,scouts:8,maxCopies:2,repeatDays:10,lead:[24,48],cooldown:[30,54]},
 meridian:{label:'Conservative regional',description:'Builds a regional network around Denver, favors smaller aircraft, and leaves a larger cash cushion.',distance:900,spread:2200,maxDistance:3000,maxSeats:145,seats:78,regions:['North America'],hub:.5,repeat:.1,scarcity:.05,contest:0,reserve:1.4,scouts:10,maxCopies:2,repeatDays:8,lead:[18,36],cooldown:[36,60]},
 solstice:{label:'Patient international',description:'Saves for longer international connections and larger aircraft. Expands selectively instead of chasing every opening.',distance:6500,spread:6000,minDistance:3000,seats:260,regions:['Europe'],hub:.15,repeat:.02,scarcity:.02,contest:0,reserve:1.5,scouts:8,maxCopies:2,repeatDays:12,lead:[24,48],cooldown:[48,72]},
 nimbus:{label:'High-volume challenger',description:'Favors affordable, busy routes and efficient medium aircraft. Adds capacity where it can compete on operating costs.',distance:1800,spread:3500,maxDistance:6000,maxSeats:244,seats:145,regions:['North America','Europe'],hub:.1,repeat:.25,scarcity:.15,contest:.12,reserve:1.15,scouts:12,maxCopies:3,repeatDays:5,lead:[12,24],cooldown:[18,36]},
 pacifica:{label:'Pacific hub builder',description:'Concentrates on Asia and Oceania, grows connecting hubs, and expands successful routes patiently.',distance:3000,spread:5000,seats:189,regions:['Asia','Oceania'],regionalOnly:true,hub:.4,repeat:.15,scarcity:.08,contest:.02,reserve:1.3,scouts:10,maxCopies:3,repeatDays:9,lead:[24,42],cooldown:[30,54]},
 kestrel:{label:'Emerging-market explorer',description:'Tries overlooked destinations and quieter connections with modest aircraft. Varies its bets rather than dominating one route.',distance:2200,spread:4500,maxSeats:244,seats:100,regions:[],hub:.1,repeat:.03,scarcity:0,contest:-.1,reserve:1.25,scouts:8,maxCopies:2,repeatDays:6,lead:[18,42],cooldown:[24,48]}
};
export const aiStrategy=ai=>AI_STRATEGIES[ai.id]||AI_STRATEGIES.kestrel;
const aiNoise=text=>{let n=2166136261;for(const ch of text){n^=ch.charCodeAt(0);n=Math.imul(n,16777619);}return (n>>>0)/4294967296;};
function aiMarketFit(ai,a,b){const p=aiStrategy(ai),km=distance(a,b),region=p.regions.some(region=>ap(a).region===region||ap(b).region===region);if(km<(p.minDistance||350)||km>(p.maxDistance||18000)||(p.regionalOnly&&!region))return 0;return (.65+.5*Math.max(0,1-Math.abs(km-p.distance)/p.spread))*(region?1.25:1);}
export function aiCanExpandConnection(s,ai,a,b){const p=aiStrategy(ai),existing=ai.routes.filter(r=>r.id===key(a,b));return remainingLicenses(s,a,b)>0&&existing.length<p.maxCopies&&!existing.some(r=>Number.isFinite(r.acquiredDay)&&gameDay(s)-r.acquiredDay<p.repeatDays);}
export function aiDecisionDelay(s,ai,kind='lead'){const p=aiStrategy(ai),[low,high]=kind==='lead'?p.lead:p.cooldown;return Math.round((low+(high-low)*aiNoise(ai.id+':'+kind+':'+(ai.expansionTurn??s.aiTurn)+':'+gameDay(s)))*60);}

// Score an expansion using post-entry competition and real operating/lease costs.
export function aiRouteOpportunity(s,ai,a,b,models=releasedPlanes(s)){
 if(!airportOpen(s,a)||!airportOpen(s,b)||a===b||!remainingLicenses(s,a,b))return null;
 const profile=aiStrategy(ai),fit=aiMarketFit(ai,a,b);if(!fit)return null;
 const km=distance(a,b),fee=licensePrice(a,b),preview={...s,rivals:s.rivals.map(x=>x.id===ai.id?{...x,routes:[...x.routes,{id:key(a,b),a,b}]}:x)};
 const existing=ai.routes.filter(r=>r.id===key(a,b)),cannibalization=existing.reduce((loss,r)=>{const p={model:r.model,acquiredDay:r.acquiredDay||0},before=economics(s,r,p,{rivals:true}),after=economics(preview,r,p,{rivals:true});return loss+(before.profit-after.profit)*1440/before.duration;},0);
 let best=null;
 for(const m of models){
  if(m.range<km||m.seats>(profile.maxSeats||1000))continue;
  const upfront=fee+Math.round(m.price*.14),rent=m.price*.018,e=economics(preview,{a,b},{model:m.id,acquiredDay:gameDay(s)},{rivals:true}),daily=e.profit*1440/e.duration-rent-cannibalization,reserve=Math.max(50000,rent*3+(e.fuel+e.crew+e.maintenance+e.fees)*2)*profile.reserve;
  if(daily<1500||ai.cash<upfront+reserve||upfront/daily>120)continue;
  const hubRoutes=ai.routes.filter(r=>r.a===a||r.b===a||r.a===b||r.b===b).length,hub=a===ai.base||b===ai.base,contested=s.planes.some(p=>p.auto&&p.schedule.includes(key(a,b))),scarce=remainingLicenses(s,a,b)<=2;
  const strategy=existing.length?'Defend a profitable connection':scarce?'Secure scarce profitable capacity':hub||hubRoutes>=2?'Strengthen a profitable hub':contested?'Compete on a profitable connection':'Expand to a profitable market';
  const aircraftFit=.8+.35*Math.max(0,1-Math.abs(m.seats-profile.seats)/250),quiet=profile===AI_STRATEGIES.kestrel?.22/(1+slots(s,a,b)):0;
  const score=daily*Math.sqrt(100000/upfront)*fit*aircraftFit*(1+(hub?profile.hub:0)+Math.min(.2,hubRoutes*.035)+(scarce?profile.scarcity:0)+(existing.length?profile.repeat:0)+(contested?profile.contest:0)+quiet);
  if(!best||score>best.score)best={a,b,model:m.id,daily,upfront,reserve,score,strategy,cannibalization};
 }
 return best;
}
export function chooseAIRoute(s,ai){
 const profile=aiStrategy(ai),frequency=new Map([[ai.base,10]]);for(const r of ai.routes)for(const id of [r.a,r.b])frequency.set(id,(frequency.get(id)||0)+1);
 const origins=[...new Set([ai.base,...[...frequency].sort((a,b)=>b[1]-a[1]).slice(0,4).map(([id])=>id),...connected(s).slice(0,3)])],seen=new Set(),candidates=[],models=releasedPlanes(s).filter(m=>ai.cash>m.price*.14+50000),maxRange=Math.max(0,...models.map(m=>m.range));
 for(const a of origins)for(const dest of openAirports(s)){
  const b=dest.id,id=key(a,b);if(a===b||seen.has(id)||!aiCanExpandConnection(s,ai,a,b)||!aiMarketFit(ai,a,b))continue;seen.add(id);
  const km=distance(a,b);if(km<350||km>maxRange)continue;
  candidates.push({a,b,potential:(ap(a).demand+dest.demand)/(1+km/6000)*aiMarketFit(ai,a,b)*(1+(a===ai.base||b===ai.base?profile.hub:0)+(remainingLicenses(s,a,b)<=2?profile.scarcity:0)+(ai.routes.some(r=>r.id===id)?profile.repeat:0))});
 }
 // Limited, imperfect scouting: each airline considers a different small sample, then varies among close choices.
 const seed=ai.id+':'+(ai.expansionTurn??s.aiTurn)+':'+gameDay(s),scouted=candidates.sort((a,b)=>b.potential-a.potential).slice(0,48).map(r=>({...r,attention:r.potential*(.55+.9*aiNoise(seed+key(r.a,r.b)))})).sort((a,b)=>b.attention-a.attention).slice(0,profile.scouts);
 const options=scouted.map(r=>aiRouteOpportunity(s,ai,r.a,r.b,models)).filter(Boolean).map(r=>({...r,score:r.score*(.88+.24*aiNoise(seed+':estimate:'+key(r.a,r.b)))})).sort((a,b)=>b.score-a.score);
 if(!options.length)return null;const shortlist=options.filter(r=>r.score>=options[0].score*.8).slice(0,3),roll=aiNoise(seed+':choice'),index=roll<.6?0:roll<.88?1:2;return shortlist[Math.min(index,shortlist.length-1)];
}


export function aiAircraftUpgrade(s,ai,r){
 const current=model(r.model),old=economics(s,r,{model:r.model,acquiredDay:r.acquiredDay||0},{rivals:true}),oldDaily=old.profit*1440/old.duration-(r.leased?current.price*.018:0);
 let best=null;
 for(const m of releasedPlanes(s).filter(m=>m.family===current.family&&m.generation>current.generation&&m.range>=distance(r.a,r.b))){
  const e=economics(s,r,{model:m.id,acquiredDay:gameDay(s)},{rivals:true}),daily=e.profit*1440/e.duration-m.price*.018,gain=daily-oldDaily,cost=Math.round(m.price*.14),reserve=Math.max(50000,m.price*.018*3+(e.fuel+e.crew+e.maintenance+e.fees)*2);
  if(daily<=0||gain<1500||cost/gain>90||ai.cash<cost+reserve)continue;
  if(!best||gain>best.gain)best={model:m.id,daily,gain,cost};
 }
 return best;
}

function aiAdvance(s,dt){for(const ai of s.rivals){for(const r of ai.routes){if(r.leased)ai.cash-=model(r.model).price*.018*dt/1440;const e=r.flight||(r.flight=economics(s,r,{model:r.model,acquiredDay:r.acquiredDay||0},{rivals:true}));r.progress+=dt;while(r.progress>=e.duration){r.progress-=e.duration;ai.cash+=e.profit;ai.revenue+=e.revenue;ai.flights++;r.flight=null;const upgrade=aiAircraftUpgrade(s,ai,r);if(upgrade){const newer=model(upgrade.model);ai.cash-=upgrade.cost;r.model=newer.id;r.leased=true;r.acquiredDay=gameDay(s);if(ai.lastModernized!==gameDay(s)){log(s,`${ai.name} is modernizing its fleet with ${newer.name}.`,'rival');ai.lastModernized=gameDay(s);}}for(const id of [r.a,r.b])if(s.airports.includes(id)){const fee=Math.round(e.revenue/2*airportShare(s));s.cash+=fee;s.totals.airport+=fee;}}} }
if(!s.started)return;
// Old saves join the independent schedule gradually, without replaying missed purchases.
initializeAISchedules(s);
for(const ai of s.rivals){
 if(ai.bid&&s.minute>=ai.bid.at){
  const b=ai.bid,choice=aiCanExpandConnection(s,ai,b.a,b.b)?aiRouteOpportunity(s,ai,b.a,b.b):null;
  if(choice){ai.cash-=choice.upfront;ai.routes.push({id:key(b.a,b.b),a:b.a,b:b.b,model:choice.model,leased:true,acquiredDay:gameDay(s),progress:0});log(s,`${ai.name} secured a license on ${b.a}–${b.b}. ${remainingLicenses(s,b.a,b.b)} of ${ROUTE_LICENSE_LIMIT} licenses remain.`,'rival');}
  else log(s,!remainingLicenses(s,b.a,b.b)?`${ai.name} missed ${b.a}–${b.b}: all ${ROUTE_LICENSE_LIMIT} licenses are owned.`:`${ai.name} passed on ${b.a}–${b.b}: the return no longer justifies the investment.`,'rival');
  ai.bid=null;ai.expansionStatus='scouting';ai.nextExpansionAt=s.minute+aiDecisionDelay(s,ai,'cooldown');
 }
 if(ai.bid||s.minute<ai.nextExpansionAt)continue;
 if(ai.routes.length>=Math.min(80,24+Math.floor(gameDay(s)/30)*8)){ai.expansionStatus='capacity';ai.nextExpansionAt=s.minute+1440;continue;}
 const choice=chooseAIRoute(s,ai);
 if(choice){
  ai.bid={rival:ai.id,a:choice.a,b:choice.b,at:s.minute+aiDecisionDelay(s,ai),model:choice.model,expectedDaily:Math.round(choice.daily),strategy:choice.strategy};
  ai.expansionStatus='planned';
  log(s,`${ai.name} plans to claim ${choice.a}–${choice.b} in ${Math.round((ai.bid.at-s.minute)/60)} game hours. ${choice.strategy}.`,'rival');
 }else{ai.expansionStatus='watching';ai.nextExpansionAt=s.minute+aiDecisionDelay(s,ai,'cooldown');}
 ai.expansionTurn++;s.aiTurn++;
}}

// Keep the old optional global bid readable until the first simulation step migrates it.
export const rivalPlans=s=>s.rivals.map(ai=>ai.bid||(s.aiBid?.rival===ai.id?s.aiBid:null)).filter(Boolean).sort((a,b)=>a.at-b.at);
function initializeAISchedules(s){
 for(const [i,ai] of s.rivals.entries()){
  if(ai.nextExpansionAt===undefined)ai.nextExpansionAt=s.minute+(i+1)*180;
  if(ai.expansionTurn===undefined)ai.expansionTurn=0;
  if(ai.expansionStatus===undefined)ai.expansionStatus='scouting';
 }
 if(s.aiBid){const ai=s.rivals.find(ai=>ai.id===s.aiBid.rival);ai.bid=s.aiBid;ai.expansionStatus='planned';s.aiBid=null;}
}


export function advance(s,minutes){if(!Number.isFinite(minutes)||minutes<0)throw Error('Invalid simulation time.');minutes=Math.min(minutes,10080);if(s.started&&minutes>0)C.initializeCareer(s);if(s.started&&minutes>0&&!s.worldEvents)advanceWorld(s);let remaining=minutes;while(remaining>0){const dt=Math.min(5,remaining),oldDay=Math.floor(s.minute/1440);s.minute+=dt;remaining-=dt;if(!s.started)continue;if(gameDay(s)>oldDay)advanceWorld(s);
for(const p of s.planes){if(p.repair>0){p.repair=Math.max(0,p.repair-dt);continue;}if(!p.schedule.length)continue;if(!p.flight&&p.auto){const r=s.routes.find(r=>r.id===p.schedule[p.leg%p.schedule.length]);if(!r)continue;const e=economics(s,r,p);p.flight={...e,route:r.id,careerFlight:{departedAt:s.minute,cabin:p.cabin,fuelPerSeat:model(p.model).burn/model(p.model).seats}};p.progress=0;}if(!p.flight)continue;p.progress+=dt;const e=p.flight;if(p.progress>=e.duration){p.progress=0;const r=s.routes.find(r=>r.id===e.route);money(s,e.profit,`Flight · ${r.a}–${r.b} · ${p.id}`,'flight');for(const k of ['revenue','fuel','crew','maintenance','fees'])s.totals[k]+=e[k];s.totals.flights++;s.totals.passengers+=e.pax;p.flights++;p.revenue+=e.revenue;r.flights++;r.revenue+=e.revenue;C.recordCareerFlight(s,r,e,notify);p.condition=Math.max(0,p.condition-e.duration/220);for(const id of [r.a,r.b])if(s.airports.includes(id)){const fee=Math.round(e.revenue/2*airportShare(s));s.cash+=fee;s.totals.airport+=fee;}s.reputation=Math.min(s.upgrades.includes('service')?100:95,s.reputation+.015);p.flight=null;p.leg=(p.leg+1)%p.schedule.length;if(p.condition<35){p.condition=100;p.repair=120;log(s,`${p.id} is in scheduled maintenance. Its operating reserve covers the service.`);} }}
const airport=s.airports.reduce((n,id)=>n+ap(id).demand*47000*worldEffects(s,id,id).demand*worldEffects(s,id,id).yield*airportShare(s)*dt/1440,0);s.cash+=airport;s.totals.airport+=airport;const interest=s.debt*.002*dt/1440;s.cash-=interest;s.totals.interest+=interest;for(const p of s.planes)if(p.leased){const cost=(p.leaseRate??model(p.model).price*.018)*dt/1440;s.cash-=cost;s.totals.leases+=cost;}aiAdvance(s,dt);const day=Math.floor(s.minute/1440);if(day>oldDay){const opens=AIRPORTS.filter(a=>a.opensDay===day),releases=PLANES.filter(p=>p.releaseDay===day),retired=PLANES.filter(p=>p.retireDay===day);if(opens.length)notify(s,{id:'airports:'+day,kind:'airports',title:opens.length+' new airports are open',message:'New destinations are ready for route licenses and airport investment.',items:opens.map(a=>a.id)});if(releases.length)notify(s,{id:'aircraft:'+day,kind:'aircraft',title:releases.length+' new aircraft models are available',message:'Explore the new models and their range, speed, fuel burn and capacity. Route-count requirements still apply.',items:releases.map(p=>p.id)});if(opens.length)log(s,`${opens.length} airports opened: ${opens.slice(0,5).map(a=>a.id).join(', ')}${opens.length>5?' and more':''}.`,'world');if(releases.length)log(s,`${releases.length} aircraft introductions: ${releases.slice(0,2).map(p=>p.name).join(', ')}. Visit the aircraft market.`,'technology');if(retired.length)log(s,`${retired.length} aircraft models moved to the legacy market. Used purchases are discounted 45%.`,'technology');s.history.push({day,cash:Math.round(s.cash),worth:Math.round(netWorth(s))});s.history=s.history.slice(-30);if(day%3===0)log(s,`${event(s).name}: ${event(s).desc}`,'market');} }
return s;}
export function validateSave(s){if(!s||s.version!==1||typeof s.name!=='string'||s.name.length>40||!Number.isFinite(s.cash)||!Number.isFinite(s.minute)||s.minute<0||!Number.isFinite(s.debt)||s.debt<0||!Number.isFinite(s.reputation)||s.reputation<0||s.reputation>100||!ap(s.home)||![0,1,5,20].includes(s.speed)||!Number.isFinite(s.lastSave)||!Number.isFinite(s.nextAI)||!Number.isFinite(s.nextId)||!Number.isFinite(s.aiTurn)||typeof s.started!=='boolean'||typeof s.bailout!=='boolean'||!/^#[0-9a-f]{6}$/i.test(s.color))throw Error('This is not a compatible Aerovale save.');for(const field of ['planes','routes','airports','claims','upgrades','rivals','history','ledger','log'])if(!Array.isArray(s[field]))throw Error('The save is incomplete.');if(s.planes.length>150||s.routes.length>5000||s.airports.length>600||(s.rivals.length<5||s.rivals.length>6))throw Error('Invalid save size.');if(!s.totals||Object.values(s.totals).some(v=>!Number.isFinite(v)||v<0))throw Error('Invalid finances.');for(const k of Object.keys(createGame().totals))if(!Number.isFinite(s.totals[k]))throw Error('Incomplete finances.');for(const r of s.routes)if(!ap(r.a)||!ap(r.b)||r.a===r.b||r.id!==key(r.a,r.b)||!Number.isFinite(r.fare)||r.fare<.7||r.fare>1.6||!Number.isFinite(r.paid)||r.paid<0||(r.licenses!==undefined&&(!Number.isInteger(r.licenses)||r.licenses<1||r.licenses>ROUTE_LICENSE_LIMIT)))throw Error('Invalid route.');for(const p of s.planes){if(!model(p.model)||typeof p.id!=='string'||!Array.isArray(p.schedule)||p.schedule.length>6||p.schedule.some(id=>!s.routes.find(r=>r.id===id))||!Number.isFinite(p.progress)||!Number.isFinite(p.condition)||!Number.isFinite(p.leg)||!Number.isFinite(p.repair)||!ap(p.base)||!['standard','dense','premium'].includes(p.cabin))throw Error('Invalid aircraft.');if((p.paid!==undefined&&(!Number.isFinite(p.paid)||p.paid<0))||(p.leaseRate!==undefined&&(!Number.isFinite(p.leaseRate)||p.leaseRate<0))||(p.acquiredDay!==undefined&&(!Number.isFinite(p.acquiredDay)||p.acquiredDay<0)))throw Error('Invalid aircraft financing.');if(p.flight&&(!s.routes.some(r=>r.id===p.flight.route)||['duration','revenue','fuel','crew','fees','maintenance','profit','pax'].some(k=>!Number.isFinite(p.flight[k]))||p.flight.duration<=0))throw Error('Invalid flight.');}if(s.airports.some(id=>!ap(id))||s.claims.some(id=>!QUESTS.some(q=>q.id===id))||s.upgrades.some(id=>!UPGRADES.some(u=>u.id===id)))throw Error('Invalid progression.');if(new Set(s.routes.map(r=>r.id)).size!==s.routes.length||new Set(s.planes.map(p=>p.id)).size!==s.planes.length||new Set(s.airports).size!==s.airports.length||new Set(s.claims).size!==s.claims.length)throw Error('Duplicate save entries.');if(new Set(s.rivals.map(ai=>ai.id)).size!==s.rivals.length||RIVALS.some(r=>!s.rivals.some(ai=>ai.id===r.id)))throw Error('Invalid rival roster.');validateWorldState(s);C.validateCareer(s);for(const l of s.log)if(typeof l.text!=='string'||typeof l.type!=='string'||!Number.isFinite(l.time))throw Error('Invalid activity log.');for(const l of s.ledger)if(typeof l.label!=='string'||typeof l.category!=='string'||!Number.isFinite(l.amount)||!Number.isFinite(l.time))throw Error('Invalid transaction log.');if(!s.history.length||s.history.some(h=>!Number.isFinite(h.day)||!Number.isFinite(h.cash)||!Number.isFinite(h.worth)))throw Error('Invalid history.');for(const ai of s.rivals)if(!allRivalDefinitions.some(r=>r.id===ai.id)||!Number.isFinite(ai.cash)||!Array.isArray(ai.routes)||ai.routes.some(r=>!ap(r.a)||!ap(r.b)||r.id!==key(r.a,r.b)||!model(r.model)||!Number.isFinite(r.progress)))throw Error('Invalid rival data.');if(s.aiBid&&(!s.rivals.some(r=>r.id===s.aiBid.rival)||!ap(s.aiBid.a)||!ap(s.aiBid.b)||!Number.isFinite(s.aiBid.at)))throw Error('Invalid rival plan.');for(const ai of s.rivals){if((ai.nextExpansionAt!==undefined&&(!Number.isFinite(ai.nextExpansionAt)||ai.nextExpansionAt<0))||(ai.expansionTurn!==undefined&&(!Number.isInteger(ai.expansionTurn)||ai.expansionTurn<0))||(ai.expansionStatus!==undefined&&!['scouting','planned','watching','capacity'].includes(ai.expansionStatus)))throw Error('Invalid rival schedule.');if(ai.bid&&(ai.bid.rival!==ai.id||!ap(ai.bid.a)||!ap(ai.bid.b)||ai.bid.a===ai.bid.b||!Number.isFinite(ai.bid.at)||ai.bid.at<0))throw Error('Invalid rival plan.');for(const r of ai.routes)if(r.flight&&(['duration','revenue','profit'].some(k=>!Number.isFinite(r.flight[k]))||r.flight.duration<=0))throw Error('Invalid rival flight.');const original=allRivalDefinitions.find(r=>r.id===ai.id);for(const k of ['name','color','initial','style','base'])ai[k]=original[k];}return s;}

export function replacePlane(s,id,nextModel){const p=s.planes.find(p=>p.id===id),m=model(nextModel);if(!p||!m)throw Error('Choose an aircraft and its replacement.');if(p.flight)throw Error('Pause departures and finish the current flight before replacing this aircraft.');if(p.model===nextModel)throw Error('Choose a different model.');if(modelStatus(s,m)==='upcoming'||s.routes.length<m.unlock)throw Error('This replacement is not available yet.');if(p.schedule.some(id=>{const r=s.routes.find(r=>r.id===id);return distance(r.a,r.b)>m.range;}))throw Error('The replacement cannot fly all routes in this rotation.');const price=aircraftPrice(s,nextModel),trade=resaleValue(s,p);pay(s,Math.max(0,price-trade));money(s,trade,`Trade-in · ${p.id}`,'investment');money(s,-price,`Replacement · ${m.name}`,'investment');const old=model(p.model).name;p.model=nextModel;p.leased=false;p.paid=price;p.leaseRate=0;p.acquiredDay=gameDay(s);p.condition=100;p.repair=0;p.progress=0;s.totals.replacements=(s.totals.replacements||0)+1;log(s,`${p.id} upgraded from ${old} to ${m.name}. Its rotation is preserved.`);return p;}
